import React,{useState,useRef,useEffect,useLayoutEffect} from 'react';
import {createRoot} from 'react-dom/client';
import {LayoutDashboard, Trophy, Settings, ArrowUpRight, ArrowRight, Plus, ChevronUp, ChevronDown, X, Users, Gem, Check, Download, Upload, Maximize, Volume2, VolumeX, BookOpen, Play, RotateCcw, ShieldCheck, Ellipsis, Flag, Sparkles, Copy, Search, Trash2, HelpCircle} from 'lucide-react';
import {APP_TITLE,CATALOG} from './catalog';
import {uid,createSeason,makeRound,makeMatch,ranking,totals,calculate,preview,pay,cancelRound,buyTicket,refundTicket,transaction,checkStudents,validateBackup,integer,type State,type Round,type Student,type Entry,type Rule,type Kind} from './core';
import {KEY,load,persist,download} from './storage';
import './style.css';
const STATUS={scheduled:'예정',playing:'진행 중',draft:'결과 작성 중',paid:'지급 완료'};
const KINDS:Record<Kind,string>={start:'시작 지급',reward:'게임 보상',bonus:'획득 보너스',purchase:'추가 구입',ticket:'이용권 구매',refund:'이용권 환불',adjust:'잔액 조정',reversal:'지급 취소'};
const fmt=(n:number)=>n.toLocaleString('ko-KR');
const date=(s:string)=>new Date(s).toLocaleString('ko-KR',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
const num=(s:string)=>s.trim()===''?0:Number(s);
type Modal={type:'create'|'manage'|'round'|'student'|'backup'|'help'|'settings';id?:string}|null;
function Diamond({className=''}:{className?:string}){return <svg className={'diamond '+className} viewBox="0 0 64 70" aria-hidden="true"><path d="M17 3 47 3 62 24 48 54 32 68 16 54 2 24Z" fill="#a43b50"/><path d="m17 3 15 21H2Zm30 0L32 24h30ZM2 24l30 44V24Z" fill="#d57482"/><path d="M62 24 32 68V24Z" fill="#6d2035"/><path d="M17 3h30L32 24Z" fill="#efa4ab"/><path d="M16 54 2 24h30Z" fill="#b84b63"/></svg>}
function ModalBox({title,eyebrow='TEACHER’S ROOM',children,close,wide=false}:{title:string;eyebrow?:string;children:React.ReactNode;close:()=>void;wide?:boolean}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const before=document.activeElement as HTMLElement|null;const el=ref.current;el?.focus();const h=(e:KeyboardEvent)=>{if(e.key==='Escape')close();if(e.key==='Tab'&&el){const nodes=[...el.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,textarea,[tabindex="0"]')];if(nodes.length){if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus();}}}};document.addEventListener('keydown',h);return()=>{document.removeEventListener('keydown',h);before?.focus();};},[]);return <div className="modal-shade" onClick={e=>{if(e.target===e.currentTarget)close();}}><div className={'modal '+(wide?'wide':'')} role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} ref={ref}><header className="modal-head"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div><button className="icon" aria-label="닫기" onClick={close}><X/></button></header>{children}</div></div>}
function Field({label,children,hint}:{label:string;children:React.ReactNode;hint?:string}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function App(){
 const initial=useRef(load()).current;const [s,setS]=useState<State|null>(initial.state);const current=useRef(s);const [error,setError]=useState(initial.error??'');const [modal,setModal]=useState<Modal>(null);const [page,setPage]=useState<'dashboard'|'ranking'>('dashboard');const [filter,setFilter]=useState<'all'|'scheduled'|'paid'>('all');const [search,setSearch]=useState('');const [rankPage,setRankPage]=useState(0);const [busy,setBusy]=useState(0);const [notice,setNotice]=useState('');const [reveal,setReveal]=useState<Round|null>(null);const queue=useRef(Promise.resolve());const [conflict,setConflict]=useState(false);
 useEffect(()=>{const h=(e:StorageEvent)=>{if(e.key===KEY)setConflict(true);};window.addEventListener('storage',h);return()=>window.removeEventListener('storage',h);},[]);
 useEffect(()=>{if(notice){const t=setTimeout(()=>setNotice(''),4500);return()=>clearTimeout(t);}},[notice]);
 const act=(fn:(x:State)=>State,success='',replace?:State):Promise<boolean>=>{setBusy(n=>n+1);let result=false;const task=queue.current.then(async()=>{try{if(conflict&&!replace)throw Error('다른 탭에서 변경되었습니다. 새로고침 후 이어서 진행해 주세요.');const prev=current.current;const next=replace??(prev?fn(prev):null);if(!next)throw Error('시즌을 먼저 만들어 주세요.');const saved=await persist(next,prev?.revision??null);current.current=saved;setS(saved);setError('');if(success)setNotice(success);result=true;}catch(e){setError(e instanceof Error?e.message:'처리하지 못했습니다.');}finally{setBusy(n=>n-1);}});queue.current=task;return task.then(()=>result);};
 const close=()=>setModal(null);const ranked=s?ranking(s):[];const round=s?.rounds.find(r=>r.status==='playing'||r.status==='draft')??s?.rounds.find(r=>r.status==='scheduled');const done=s?.rounds.filter(r=>r.status==='paid').length??0;
 const updateRound=(id:string,fn:(r:Round,x:State)=>Round)=>act(x=>({...x,rounds:x.rounds.map(r=>r.id===id?fn(r,x):r)}));
 const start=async(r:Round)=>{if(s?.rounds.some(x=>x.id!==r.id&&(x.status==='playing'||x.status==='draft'))){setError('진행 중인 회차의 지급을 먼저 완료해 주세요.');return;}if(await act(x=>({...x,status:'active',rounds:x.rounds.map(q=>q.id===r.id?{...q,status:'playing',matches:q.matches.length?q.matches:[makeMatch(x)]}:q)}),'보상 설정을 확정하고 회차를 시작했습니다.'))setModal({type:'round',id:r.id});};
 const doPay=async(r:Round)=>{try{const rows=preview(r);if(!await ask(`${rows.filter(x=>x.count).length}명에게 총 ${rows.reduce((n,x)=>n+x.total,0)}가넷을 지급하고 결과를 공개할까요?`))return;if(await act(x=>pay(x,r.id),'장부가 저장되었습니다.')){close();const paid=current.current!.rounds.find(x=>x.id===r.id)!;setReveal(paid);sound();}}catch(e){setError((e as Error).message);}};
 function sound(){if(!current.current?.settings.sound)return;try{const ac=new AudioContext();[523,659,784].forEach((f,i)=>{const osc=ac.createOscillator(),gain=ac.createGain();osc.connect(gain);gain.connect(ac.destination);osc.frequency.value=f;gain.gain.setValueAtTime(0,ac.currentTime+i*.13);gain.gain.linearRampToValueAtTime(.06,ac.currentTime+i*.13+.02);gain.gain.exponentialRampToValueAtTime(.001,ac.currentTime+i*.13+.4);osc.start(ac.currentTime+i*.13);osc.stop(ac.currentTime+i*.13+.45);});setTimeout(()=>void ac.close(),1200);}catch{}}
 const fullscreen=()=>{if(document.fullscreenElement)void document.exitFullscreen();else void document.documentElement.requestFullscreen().catch(()=>setNotice('이 환경에서는 전체 화면을 지원하지 않습니다. 브라우저 F11을 사용해 주세요.'));};
 const newDemo=async()=>{if(current.current&&!await ask('현재 시즌을 교체합니다. 백업 후 진행해 주세요. 체험 시즌을 열까요?'))return;const d=createSeason('우리 반의 첫 번째 도전 · 체험','6학년 지니어스',Array.from({length:16},(_,i)=>`${i+1} 참가자 ${String(i+1).padStart(2,'0')}`).join('\n'),5,['jury','virus','bean','harvest','number','monopoly','twelve','laser','blackwhite','maze']);d.rounds[0].rule.type='direct';d.rounds[0].matches=[makeMatch(d)];d.rounds[0].matches[0].entries.forEach((e,i)=>e.direct=[8,6,6,5,4,4,3,3,2,2,1,1,1,1,0,0][i]);const paid=pay(d,d.rounds[0].id);await act(x=>x,'가상 학생으로 만든 체험 시즌입니다.',paid);};
 return <div className={'app '+(s?.settings.reduceMotion?'reduced':'')}>
 <aside className="sidebar"><a href="#" className="brand" onClick={e=>{e.preventDefault();setPage('dashboard');}}><Diamond/><div>{APP_TITLE}<small>THE GENIUS SEASON</small></div></a><div className="side-season"><span className="tiny">CLASSROOM SERIES</span><strong>{s?.className||'우리 반의 새로운 도전'}</strong><span className="live-dot">{s?s.status==='final'?'시즌 완료':s.status==='ready'?'시즌 준비 중':'시즌 진행 중':'시즌을 시작해 보세요'}</span></div><span className="nav-label">SEASON</span><nav><button className={page==='dashboard'?'active':''} onClick={async()=>setPage('dashboard')}><LayoutDashboard size={19}/> 시즌 대시보드</button><button className={page==='ranking'?'active':''} onClick={async()=>{setPage('ranking');setRankPage(0);}}><Trophy size={19}/> 전체 순위<span className="nav-count">{s?.students.filter(x=>x.active).length??0}</span></button></nav><div className="side-bottom"><div className="local-note"><ShieldCheck size={19}/><div>이 브라우저에 자동 저장<small>변경한 기록은 자동 저장됩니다.</small></div></div><button onClick={async()=>setModal({type:'help'})}><HelpCircle size={18}/> 저장 및 사용 안내</button><button onClick={async()=>setModal({type:s?'settings':'create'})}><Settings size={18}/> 교사용 관리</button><div className="side-footer">함께 생각하고, 끝까지 도전하는 우리.</div></div></aside>
 <main><header className="topbar"><div className="breadcrumb">OUR CLASS, OUR GAME <span>/</span> {s?.status==='final'?'FINAL RESULTS':page==='ranking'?'LEADERBOARD':'SEASON DASHBOARD'}</div><div className="top-actions"><span className="save-state"><i/>{busy?'저장 중…':s?'자동 저장 완료':'기기 내 저장'}</span><button className="icon" aria-label={s?.settings.sound?'효과음 끄기':'효과음 켜기'} onClick={async()=>s?void act(x=>({...x,settings:{...x.settings,sound:!x.settings.sound}})):setNotice('시즌 생성 후 효과음을 설정할 수 있습니다.')}>{s?.settings.sound?<Volume2 size={18}/>:<VolumeX size={18}/>}</button><button className="icon" aria-label="전체 화면" onClick={fullscreen}><Maximize size={18}/></button><button className="button small" onClick={async()=>setModal({type:s?'settings':'create'})}><Settings size={16}/> 교사 메뉴</button></div></header>
 {conflict&&<div className="alert">다른 탭에서 기록이 변경되었습니다. <button onClick={async()=>location.reload()}>새로고침하고 이어서 진행</button></div>}{error&&<div className="alert" role="alert">{error}<button className="icon" aria-label="오류 닫기" onClick={async()=>setError('')}><X size={16}/></button>{!s&&<button onClick={async()=>setModal({type:'backup'})}>복구 메뉴</button>}</div>}
 <div className="content"><section className="page-heading"><div><span className="eyebrow">THINK. PLAY. GROW.</span><h1>{s?.status==='final'?'우리의 도전, 빛나는 마무리':page==='ranking'?'끝까지 함께하는 순위표':s?.name||'우리 반의 도전이 시작되는 곳'}</h1><p>{s?.status==='final'?'누적 획득 가넷으로 결정된 최종 결과입니다.':page==='ranking'?'가넷을 사용해도, 도전으로 쌓은 기록은 그대로 남습니다.':'서로 다른 게임, 하나로 이어지는 우리 반의 이야기.'}</p></div><button className="button" onClick={async()=>setModal({type:s?'backup':'create'})}>{s?<Download size={16}/>:<Plus size={16}/>} {s?'시즌 백업':'새 시즌 만들기'}</button></section>
 {!s?<><section className="welcome hero"><div className="hero-copy"><span className="pill">YOUR NEXT CHAPTER</span><h2>생각을 모으고,<br/>도전을 쌓아가는 시간.</h2><p>열 가지 두뇌 게임을 하나의 시즌으로.<br/>모두가 끝까지 참여하는 우리 반만의 게임쇼를 열어 보세요.</p><div className="actions"><button className="button primary" onClick={async()=>setModal({type:'create'})}>우리 반 시즌 만들기 <ArrowRight size={18}/></button><button className="text-button" onClick={async()=>void newDemo()}>체험 시즌 살펴보기 <ArrowUpRight size={16}/></button></div></div><div className="hero-art"><div className="orbit o1"/><div className="orbit o2"/><Diamond/><span className="art-caption">EVERY CHALLENGE COUNTS</span></div></section><div className="feature-row"><div><span>01</span><h3>우리 반만의 시즌</h3><p>학생과 게임을 등록하고 보상을 정해요.</p></div><div><span>02</span><h3>도전이 쌓이는 가넷</h3><p>게임 결과를 입력하면 보상을 계산해요.</p></div><div><span>03</span><h3>함께 보는 성장의 기록</h3><p>누적 가넷으로 우리 반의 순위를 공개해요.</p></div></div><div className="section-title"><h2>열 가지 게임, 열 가지 도전 <span>THE LINEUP</span></h2></div><div className="catalog-grid">{CATALOG.map((g,i)=><article className="mini-game" key={g.id}><GameArt id={g.id}/><span>{String(i+1).padStart(2,'0')}</span><h3>{g.name}</h3></article>)}</div></>:
 <>{s.status==='final'&&<section className="final-hero"><span className="eyebrow">SEASON FINALE</span><Trophy size={38}/><h2>{ranked.filter(x=>x.rank===1).map(x=>x.name).join(' · ')||'모두의 도전'}</h2><p>{ranked.filter(x=>x.rank===1).length>1?'공동 우승':'시즌 우승'} · 누적 획득 {fmt(ranked[0]?.earned??0)} 가넷</p><small>{s.students.filter(x=>x.active).length}명 · {done}회차 완료 · {s.rounds.filter(x=>x.status==='paid').map(x=>x.name).join(' / ')}</small><button className="text-button" onClick={async()=>void act(x=>({...x,status:'active'}),'시즌 진행 상태로 돌아왔습니다.')}>시즌 이어서 진행 <ArrowRight size={16}/></button></section>}
 {page==='dashboard'&&s.status!=='final'&&<section className="hero current-hero"><div className="hero-copy"><div className="round-label"><span className="pill">{round?`ROUND ${String(s.rounds.findIndex(x=>x.id===round.id)+1).padStart(2,'0')}`:'ALL ROUNDS COMPLETE'}</span><span className="light-text">{round?STATUS[round.status]:'모든 회차 지급 완료'}</span></div><h2>{round?.name||'다음 도전을 준비할 시간'}</h2><p>{round?CATALOG.find(g=>g.id===round.gameId)?.description:'새로운 회차를 추가하거나 시즌 최종 결과를 공개해 보세요.'}</p><div className="reward-note"><Diamond/><span>{round?`참가 ${round.rule.type==='direct'?'직접 배정':round.rule.participation+' 가넷'}${round.rule.type==='winner'?` · 우승 추가 ${round.rule.winner} 가넷`:round.rule.type==='rank'?' · 순위별 추가 보상':round.rule.type==='team'?' · 팀별 추가 보상':''}`:'우리의 도전은 계속됩니다.'}</span></div><div className="actions">{round?<><button className="button primary" onClick={async()=>round.status==='scheduled'?void start(round):setModal({type:'round',id:round.id})}>{round.status==='scheduled'?<Play size={16}/>:<BookOpen size={16}/>} {round.status==='scheduled'?'이번 회차 시작':'결과 입력 · 가넷 지급'} <ArrowRight size={17}/></button><button className="text-button" onClick={async()=>setModal({type:'round',id:round.id})}>보상 및 이용권 안내 <ArrowUpRight size={16}/></button></>:<button className="button primary" onClick={async()=>setModal({type:'manage'})}>회차 추가 <Plus size={16}/></button>}</div></div><div className="current-art">{round?<GameArt id={round.gameId} large/>:<Diamond/>}</div><div className="hero-number">{round?String(s.rounds.findIndex(x=>x.id===round.id)+1).padStart(2,'0'):'✓'}</div></section>}
 <div className="stats-row"><div><Users size={19}/><span>함께하는 참가자</span><strong>{s.students.filter(x=>x.active).length}<small>명</small></strong></div><div><Flag size={19}/><span>완료한 도전</span><strong>{done}<small>/ {s.rounds.length}회차</small></strong></div><div><Gem size={19}/><span>시즌 누적 획득</span><strong>{fmt(s.students.reduce((n,x)=>n+totals(s,x.id).earned,0))}<small>가넷</small></strong></div><div className="progress-stat"><span>SEASON PROGRESS</span><strong>{s.rounds.length?Math.round(done/s.rounds.length*100):0}<small>%</small></strong><div className="progress"><i style={{width:`${s.rounds.length?done/s.rounds.length*100:0}%`}}/></div></div></div>
 <div className={page==='dashboard'?'dashboard-columns':'ranking-only'}><section className="games-section">{page==='dashboard'?<><div className="section-title"><h2>시즌 라인업 <span>THE CHALLENGES</span></h2><button className="text-button" onClick={async()=>setModal({type:'manage'})}>게임 관리 <Ellipsis size={19}/></button></div><div className="filterbar">{(['all','scheduled','paid'] as const).map(f=><button key={f} className={filter===f?'selected':''} onClick={async()=>setFilter(f)}>{f==='all'?'전체 게임':f==='scheduled'?'앞으로의 도전':'완료한 도전'} {f==='all'&&<small>{s.rounds.length}</small>}</button>)}</div><div className="game-grid">{s.rounds.filter(r=>filter==='all'||(filter==='scheduled'?r.status!=='paid':r.status==='paid')).map(r=>{const g=CATALOG.find(g=>g.id===r.gameId)!;const index=s.rounds.findIndex(x=>x.id===r.id);return <article className={'game-card '+(r.id===round?.id?'is-current':'')+(r.status==='paid'?' is-done':'')} key={r.id}><div className="game-visual"><button className="thumbnail" disabled={!g.url} onClick={async()=>{if(g.url)window.open(g.url,'_blank','noopener,noreferrer');}} aria-label={`${g.name} 외부 게임 열기${!g.url?' (주소 준비 중)':''}`}>{g.thumbnail?<img src={g.thumbnail} alt={g.name}/>:<GameArt id={g.id}/>}</button><span className="round-chip">ROUND {String(index+1).padStart(2,'0')}</span><span className={'state-chip '+r.status}>{r.status==='paid'&&<Check size={12}/>} {STATUS[r.status]}</span>{!g.url&&<span className="asset-pending">게임 주소 준비 중</span>}</div><div className="game-card-body"><div><h3>{r.name}</h3><ArrowUpRight size={18} className="muted"/></div><p>{g.description}</p><button onClick={async()=>setModal({type:'round',id:r.id})}>안내·이용권 <ArrowRight size={15}/></button></div></article>;})}</div>{!s.rounds.length&&<div className="empty"><Flag/><h3>첫 번째 게임을 골라 주세요.</h3><button className="button" onClick={async()=>setModal({type:'manage'})}>게임 추가</button></div>}</>:null}</section>
 <section className="leaderboard"><div className="section-title"><h2>{s.status==='final'?'최종 순위':'우리 반 순위'} <span>LEADERBOARD</span></h2><Trophy size={19}/></div><p className="ranking-caption">순위는 <b>누적 획득 가넷</b>으로 결정됩니다.</p>{page==='ranking'&&<label className="search"><Search size={17}/><input value={search} onChange={e=>{setSearch(e.target.value);setRankPage(0);}} placeholder="학생 이름 또는 번호 찾기"/></label>}<div className="rank-labels"><span>순위 / 참가자</span><span>누적 획득<small>현재 보유</small></span></div><div className="rank-list">{ranked.filter(x=>!search||x.name.includes(search)||x.number.includes(search)).slice(rankPage*(page==='ranking'?12:6),(rankPage+1)*(page==='ranking'?12:6)).map(x=><RankMotion rank={x.rank} earned={x.earned} className={'rank-row '+(x.rank===1?'first':'')} key={x.id} open={()=>setModal({type:'student',id:x.id})}><span className="rank-number">{x.rank===1?<Trophy size={19}/>:String(x.rank).padStart(2,'0')}</span><span className="rank-name">{x.name}<small>{x.tied?'공동 '+x.rank+'위':x.number+'번 참가자'}</small></span><span className="rank-value"><Gem size={14}/>{fmt(x.earned)}<small>보유 {fmt(x.balance)}</small></span></RankMotion>)}</div>{ranked.length===0&&<div className="empty">등록된 참가자가 없습니다.</div>}<div className="rank-pagination"><button disabled={rankPage===0} onClick={async()=>setRankPage(n=>n-1)}>이전</button><span>{rankPage+1} / {Math.max(1,Math.ceil(ranked.filter(x=>!search||x.name.includes(search)||x.number.includes(search)).length/(page==='ranking'?12:6)))}</span><button disabled={(rankPage+1)*(page==='ranking'?12:6)>=ranked.filter(x=>!search||x.name.includes(search)||x.number.includes(search)).length} onClick={async()=>setRankPage(n=>n+1)}>다음</button></div>{page==='dashboard'&&<button className="all-ranking" onClick={async()=>{setPage('ranking');setRankPage(0);}}>전체 참가자 순위 보기 <ArrowRight size={15}/></button>}<div className="rank-note"><Diamond/><p>도전으로 얻은 가넷은<br/>사용해도 순위에서 줄어들지 않아요.</p></div></section></div></>}
 <footer className="main-footer"><span>{APP_TITLE} <i/> EVERY PLAYER STAYS IN THE GAME.</span><span>{s?`마지막 저장 ${date(s.updatedAt)}`:'기록은 현재 기기와 브라우저에만 저장됩니다.'}</span></footer></div></main>
 {notice&&<div className="toast" role="status"><Check size={18}/>{notice}</div>}
 {modal?.type==='create'&&<CreateModal close={close} existing={!!s} create={async d=>{if(s&&!await ask('현재 시즌을 교체합니다. 먼저 백업했는지 확인해 주세요. 새 시즌을 만들까요?'))return;if(await act(x=>x,'시즌을 만들었습니다.',d))close();}}/>}
 {modal?.type==='help'&&<ModalBox title="기록은 어디에 저장되나요?" close={close}><div className="help-copy"><ShieldCheck size={40}/><p>학생 명단과 게임 기록은 <b>이 기기의 현재 브라우저</b>에 저장됩니다. 별도 서버로 전송하지 않습니다.</p><p>같은 기기와 브라우저에서 다시 접속하면 이어서 사용할 수 있습니다. 브라우저 데이터를 삭제하거나 다른 기기·브라우저를 사용하면 기록을 불러오지 못할 수 있으므로 정기적으로 백업해 주세요.</p><ul><li>백업 파일에도 학생 정보가 포함됩니다. 안전하게 보관해 주세요.</li><li>공용 PC에서는 사용 후 데이터 관리에 주의해 주세요.</li><li>시크릿 모드 사용을 피하고, 기기 변경 시 백업 파일로 옮겨 주세요.</li><li>브라우저 저장은 암호화된 계정 보호 기능이 아닙니다.</li><li>교사 패널도 투사 중에는 학생에게 보일 수 있습니다.</li></ul><button className="button primary" onClick={close}>확인했습니다 <Check size={16}/></button></div></ModalBox>}
 {modal?.type==='backup'&&<BackupModal s={s} close={close} restore={async d=>{if(await act(x=>x,'백업을 복구했습니다.',d)){setConflict(false);close();}}} backed={()=>void act(x=>({...x,lastBackup:new Date().toISOString()}))}/>}
 {modal?.type==='settings'&&s&&<ModalBox title="교사용 시즌 관리" close={close}><p className="panel-note">공개 화면에 투사 중인 경우 이 패널도 학생들에게 보입니다.</p><div className="menu-grid"><button onClick={async()=>setModal({type:'manage'})}><Flag/><strong>게임·보상 관리</strong><small>회차 추가와 순서, 시작 전 보상 설정</small></button><button onClick={async()=>setModal({type:'student'})}><Users/><strong>학생·가넷 장부</strong><small>명단 수정, 시작 가넷 조정, 거래 기록</small></button><button onClick={async()=>setModal({type:'backup'})}><Download/><strong>백업·복구</strong><small>전체 시즌 JSON 파일로 이동</small></button><button onClick={async()=>setModal({type:'create'})}><Plus/><strong>새 시즌 만들기</strong><small>현재 시즌을 백업한 후 새롭게 시작</small></button></div><div className="form-grid"><Field label="시즌명"><input value={s.name} onChange={e=>{const value=e.target.value;void act(x=>({...x,name:value||x.name}));}}/></Field><Field label="학급명"><input value={s.className} onChange={e=>{const value=e.target.value;void act(x=>({...x,className:value}));}}/></Field></div><label className="checkline"><input type="checkbox" checked={s.allowPurchase} onChange={e=>{const checked=e.target.checked;void act(x=>({...x,allowPurchase:checked}));}}/> 추가 가넷 구입 기록 허용 <small>순위에는 반영되지 않습니다.</small></label><label className="checkline"><input type="checkbox" checked={s.settings.reduceMotion} onChange={e=>{const checked=e.target.checked;void act(x=>({...x,settings:{...x.settings,reduceMotion:checked}}));}}/> 화면 움직임 줄이기</label><div className="modal-bottom"><button className="text-button" onClick={async()=>setModal({type:'help'})}>저장 안내 다시 보기</button><button className="button primary" disabled={busy>0} onClick={async()=>{if(await ask(s.status==='final'?'시즌을 다시 진행할까요?':`완료 ${done}/${s.rounds.length}회차입니다. 현재 기록으로 시즌 최종 결과를 공개할까요?`)){if(await act(x=>({...x,status:x.status==='final'?'active':'final'}),'시즌 상태를 변경했습니다.')){close();setPage('ranking');sound();}}}}><Trophy size={16}/>{s.status==='final'?'시즌 다시 진행':'시즌 종료 및 최종 공개'}</button></div></ModalBox>}
 {modal?.type==='manage'&&s&&<ManageModal s={s} close={close} act={act} open={id=>setModal({type:'round',id})}/>}
 {modal?.type==='student'&&s&&<StudentsModal s={s} selectedId={modal.id} close={close} act={act}/>}
 {modal?.type==='round'&&s&&s.rounds.some(r=>r.id===modal.id)&&<RoundModal s={s} r={s.rounds.find(r=>r.id===modal.id)!} close={close} update={fn=>updateRound(modal.id!,fn)} start={start} pay={doPay} busy={busy>0} act={act} replay={r=>{close();setReveal(r);sound();}}/>}
 {reveal&&s&&<Reveal s={s} r={reveal} close={()=>setReveal(null)}/>}
 </div>;
}
type Act=(fn:(s:State)=>State,success?:string,replace?:State)=>Promise<boolean>;
function RankMotion({rank,earned,className,open,children}:{rank:number;earned:number;className:string;open:()=>void;children:React.ReactNode}){const ref=useRef<HTMLButtonElement>(null);const previous=useRef<number|null>(null);useLayoutEffect(()=>{const el=ref.current;if(!el)return;const top=el.getBoundingClientRect().top;if(previous.current!==null&&previous.current!==top&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.querySelector('.app.reduced'))el.animate([{transform:`translateY(${previous.current-top}px)`},{transform:'translateY(0)'}],{duration:650,easing:'cubic-bezier(.22,.8,.3,1)'});previous.current=top;},[rank,earned]);return <button ref={ref} className={className} onClick={open}>{children}</button>}
function GameArt({id,large=false}:{id:string;large?:boolean}){const g=CATALOG.find(x=>x.id===id)!;return <div className={'game-art '+g.color+(large?' large':'')}><div className="art-grid"/><div className="art-ring"/><div className="art-shape shape-one"/><div className="art-shape shape-two"/><span className="game-symbol">{g.symbol}</span><span className="art-word">{g.id==='jury'?'THE VERDICT':g.id==='virus'?'HIDDEN CHOICE':g.id==='bean'?'THE DILEMMA':g.id==='harvest'?'ABUNDANCE':g.id==='number'?'SECRET NUMBER':g.id==='monopoly'?'MONOPOLY':g.id==='twelve'?'TWELVE MOVES':g.id==='laser'?'LIGHT & STRATEGY':g.id==='blackwhite'?'BLACK & WHITE':'MEMORY MAZE'}</span><span className="placeholder-label">시즌 아트 · 썸네일 준비 중</span></div>}
function CreateModal({close,create,existing}:{close:()=>void;create:(s:State)=>Promise<void>;existing:boolean}){const [name,setName]=useState('우리 반 지니어스 시즌');const [cl,setCl]=useState('');const [names,setNames]=useState('');const [start,setStart]=useState('5');const [ids,setIds]=useState(CATALOG.map(g=>g.id));const [agree,setAgree]=useState(false);const [error,setError]=useState('');const [busy,setBusy]=useState(false);return <ModalBox title="우리 반 시즌 만들기" close={close} wide><div className="setup-grid"><div><div className="form-grid"><Field label="시즌명"><input value={name} onChange={e=>setName(e.target.value)} maxLength={80}/></Field><Field label="학급명 · 선택"><input placeholder="예: 6학년 2반" value={cl} onChange={e=>setCl(e.target.value)} maxLength={60}/></Field></div><Field label={`참가 학생 · ${names.split('\n').filter(x=>x.trim()).length}명`} hint="한 줄에 한 명씩 입력하세요. 번호와 이름을 함께 입력할 수 있습니다. 동명이인은 번호로 구분합니다."><textarea className="names-input" value={names} onChange={e=>setNames(e.target.value)} placeholder={'1 김하늘\n2 이바다\n3 박우주'}/></Field><Field label="기본 시작 가넷" hint="보유 가넷에만 포함됩니다. 학생별 예외는 생성 후 학생 장부에서 조정할 수 있습니다."><input type="number" min="0" max="1000000" value={start} onChange={e=>setStart(e.target.value)}/></Field></div><div><h3 className="form-title">시즌에 함께할 게임 <small>{ids.length}개 선택</small></h3><div className="game-checks">{CATALOG.map(g=><label key={g.id}><input type="checkbox" checked={ids.includes(g.id)} onChange={e=>setIds(a=>e.target.checked?[...a,g.id]:a.filter(id=>id!==g.id))}/><span>{g.symbol}</span>{g.name}</label>)}</div><p className="panel-note">게임 순서와 보상은 생성 후 설정할 수 있습니다. 실제 주소·썸네일·이용권 정보는 제공 전까지 비활성화됩니다.</p></div></div><div className="storage-consent"><ShieldCheck size={20}/><div><strong>이 기기의 브라우저에 기록을 저장합니다.</strong><p>학생 정보는 서버로 전송하지 않습니다. 브라우저 데이터 삭제·시크릿 모드·기기 변경 시 기록이 사라질 수 있습니다. 정기적으로 백업하고 학생 정보가 담긴 백업을 안전하게 보관해 주세요. 브라우저 저장은 암호화된 계정 보호 기능이 아닙니다. 공용 PC 사용 후 데이터 관리에 주의해 주세요.</p><label className="checkline"><input type="checkbox" checked={agree} onChange={e=>setAgree(e.target.checked)}/>저장 방식을 이해했으며 백업 안내를 확인했습니다.</label></div></div>{error&&<p className="inline-error" role="alert">{error}</p>}<div className="modal-bottom"><small>{existing?'새 시즌을 만들면 현재 시즌을 교체합니다. 먼저 백업해 주세요.':'모든 학생이 끝까지 참여합니다. 탈락은 없습니다.'}</small><button className="button primary" disabled={!agree||busy} onClick={async()=>{try{setBusy(true);const s=createSeason(name,cl,names,num(start),ids);await create(s);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}>시즌 만들기 <ArrowRight size={17}/></button></div></ModalBox>}
function ManageModal({s,close,act,open}:{s:State;close:()=>void;act:Act;open:(id:string)=>void}){const [id,setId]=useState(CATALOG[0].id);const move=(rid:string,dir:number)=>void act(x=>{const a=[...x.rounds],i=a.findIndex(r=>r.id===rid),j=i+dir;if(j<0||j>=a.length||a[i].status!=='scheduled'||a[j].status!=='scheduled')throw Error('예정 회차끼리만 순서를 변경할 수 있습니다.');[a[i],a[j]]=[a[j],a[i]];return {...x,rounds:a};});return <ModalBox title="시즌 라인업 관리" close={close}><p className="panel-note">같은 게임을 여러 번 추가할 수 있습니다. 시작한 회차의 기록은 보존합니다.</p><div className="add-round"><select aria-label="추가할 게임" value={id} onChange={e=>setId(e.target.value)}>{CATALOG.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select><button className="button primary" onClick={async()=>void act(x=>({...x,rounds:[...x.rounds,makeRound(id)]}),'새 회차를 추가했습니다.')}><Plus size={16}/> 회차 추가</button></div><div className="manage-list">{s.rounds.map((r,i)=><div key={r.id}><span className="manage-no">{String(i+1).padStart(2,'0')}</span><button className="manage-name" onClick={async()=>open(r.id)}><strong>{r.name}</strong><small>{STATUS[r.status]} · 보상 설정 열기</small></button><button className="icon" aria-label={`${r.name} 위로`} disabled={r.status!=='scheduled'||i===0||s.rounds[i-1].status!=='scheduled'} onClick={async()=>move(r.id,-1)}><ChevronUp size={18}/></button><button className="icon" aria-label={`${r.name} 아래로`} disabled={r.status!=='scheduled'||i===s.rounds.length-1||s.rounds[i+1].status!=='scheduled'} onClick={async()=>move(r.id,1)}><ChevronDown size={18}/></button><button className="icon danger" aria-label={`${r.name} 회차 제거`} disabled={r.status!=='scheduled'} onClick={async()=>{if(await ask(`${r.name} 예정 회차를 제거할까요?`))void act(x=>{if(x.rounds.find(y=>y.id===r.id)?.status!=='scheduled')throw Error('예정 회차만 제거할 수 있습니다.');return {...x,rounds:x.rounds.filter(y=>y.id!==r.id)};});}}><Trash2 size={16}/></button></div>)}</div></ModalBox>}
function RuleEditor({r,update}:{r:Round;update:(rule:Rule)=>void}){const rule=r.rule;const field=(label:string,key:'participation'|'winner')=><Field label={label}><input type="number" min="0" max="1000000" value={rule[key]} onChange={e=>update({...rule,[key]:num(e.target.value)})}/></Field>;return <div className="rule-editor"><Field label="보상 방식"><select value={rule.type} onChange={e=>update({...rule,type:e.target.value as Rule['type']})}><option value="winner">우승자형</option><option value="rank">순위형</option><option value="team">팀 결과형</option><option value="direct">직접 배정형</option></select></Field>{rule.type!=='direct'&&field('실제 참가자 공통 보상','participation')}{rule.type==='winner'&&field('우승자 추가 보상','winner')}{rule.type==='rank'&&<Field label="순위별 추가 보상 (1위부터 쉼표 구분)"><input value={rule.ranks.join(',')} onChange={e=>update({...rule,ranks:e.target.value.split(',').map(num)})}/></Field>}{rule.type==='team'&&<div className="team-rules">{Object.entries(rule.teams).map(([team,value])=><div className="team-rule" key={team}><span>{team} 추가</span><input type="number" min="0" value={value} onChange={e=>update({...rule,teams:{...rule.teams,[team]:num(e.target.value)}})}/><button className="icon" aria-label={`${team} 제거`} onClick={async()=>{const teams={...rule.teams};delete teams[team];update({...rule,teams});}}><X size={14}/></button></div>)}<button className="text-button" onClick={async()=>{const name=await askText('추가할 팀 이름');if(name?.trim()&&!(name.trim() in rule.teams))update({...rule,teams:{...rule.teams,[name.trim()]:0}});}}>팀 추가 <Plus size={14}/></button></div>}<p className="panel-note">{rule.type==='winner'?`예상 지급: 참가자 ${rule.participation}가넷 · 우승자 ${rule.participation+rule.winner}가넷 (참가 + 추가)`:rule.type==='rank'?`공동 순위는 같은 추가 보상을 받습니다. 미설정 순위는 참가 ${rule.participation}가넷만 지급합니다.`:rule.type==='team'?'팀별 추가 보상은 해당 팀의 참가 학생마다 지급합니다.':'학생별 지급량을 직접 입력합니다.'}</p></div>}
function RoundModal({s,r,close,update,start,pay,busy,act,replay}:{s:State;r:Round;close:()=>void;update:(fn:(r:Round,s:State)=>Round)=>Promise<boolean>;start:(r:Round)=>Promise<void>;pay:(r:Round)=>Promise<void>;busy:boolean;act:Act;replay:(r:Round)=>void}){
 const [tab,setTab]=useState<'guide'|'result'|'tickets'>(r.status==='playing'||r.status==='draft'?'result':'guide');const [matchIndex,setMatchIndex]=useState(0);const [previewOn,setPreviewOn]=useState(false);const [buyer,setBuyer]=useState(s.students.find(x=>x.active)?.id??'');const [editingRule,setEditingRule]=useState(false);const g=CATALOG.find(x=>x.id===r.gameId)!;const m=r.matches[Math.min(matchIndex,r.matches.length-1)];const editable=r.status==='playing'||r.status==='draft';let rows:ReturnType<typeof preview>=[],validation='';try{rows=preview(r);}catch(e){validation=(e as Error).message;}
 useEffect(()=>{setPreviewOn(false);},[r.matches,r.rule]);
 const patch=(studentId:string,part:Partial<Entry>)=>void update(x=>{if(!['playing','draft'].includes(x.status))throw Error('이 회차의 결과는 변경할 수 없습니다.');return {...x,status:'draft',matches:x.matches.map(q=>q.id===m?.id?{...q,entries:q.entries.map(e=>e.studentId===studentId?{...e,...part}:e)}:q)};});
 const updateRule=(rule:Rule)=>void update(x=>{if(x.status==='paid')throw Error('지급 완료 회차의 보상은 바꿀 수 없습니다. 먼저 지급 취소를 진행해 주세요.');return {...x,rule,changes:x.status==='scheduled'?x.changes:[...x.changes,{at:new Date().toISOString(),rule:x.rule}]};});
 return <ModalBox title={r.name} eyebrow={`ROUND ${String(s.rounds.findIndex(x=>x.id===r.id)+1).padStart(2,'0')} · ${STATUS[r.status]}`} close={close} wide><div className="tabs">{(['guide','result','tickets'] as const).map(t=><button key={t} className={tab===t?'selected':''} onClick={async()=>setTab(t)}>{t==='guide'?'게임 안내·보상':t==='result'?'결과 입력·지급':'이용권 기록'}</button>)}</div>
 {tab==='guide'&&<div className="round-guide"><div><GameArt id={g.id}/><h3>{g.description}</h3><p className="panel-note">기존 외부 게임에서 진행한 뒤 이 서비스에서 교사가 결과를 입력합니다. 가넷은 개별 게임에서 사용되지 않습니다.</p><button className="button" disabled={!g.url} onClick={async()=>g.url&&window.open(g.url,'_blank','noopener,noreferrer')}>{g.url?'외부 게임 열기':'게임 주소 준비 중'} <ArrowUpRight size={16}/></button><div className="ticket-box"><Gem/><h3>{g.product.name}</h3><p>{g.product.description}</p><small>이용권의 편의 사항은 게임 진행 시 선생님이 적용합니다.</small><div className="add-round"><select aria-label="구매 학생" value={buyer} onChange={e=>setBuyer(e.target.value)}>{s.students.filter(x=>x.active).map(x=><option value={x.id} key={x.id}>{x.number} {x.name} · 보유 {totals(s,x.id).balance}</option>)}</select><button className="button" disabled={!g.product.enabled||g.product.price===null} onClick={async()=>{if(await ask(`${g.product.price}가넷으로 이용권을 구매할까요?`))void act(x=>buyTicket(x,r.id,buyer),'이용권을 발급했습니다.');}}>{g.product.price===null?'구매 준비 중':g.product.price+'가넷 구매'}</button></div></div></div><div><h3>이번 회차 보상 설정</h3>{r.status==='scheduled'||editingRule?<RuleEditor r={r} update={updateRule}/>:<><div className="rule-summary"><strong>{r.rule.type==='winner'?'우승자형':r.rule.type==='rank'?'순위형':r.rule.type==='team'?'팀 결과형':'직접 배정형'}</strong><p>참가 공통 {r.rule.type==='direct'?0:r.rule.participation} 가넷</p>{r.rule.type==='winner'&&<p>우승 추가 {r.rule.winner} 가넷</p>}{r.rule.type==='rank'&&r.rule.ranks.map((n,i)=><p key={i}>{i+1}위 추가 {n} 가넷</p>)}{r.rule.type==='team'&&Object.entries(r.rule.teams).map(([t,n])=><p key={t}>{t} 추가 {n} 가넷</p>)}</div>{editable&&<button className="text-button" onClick={async()=>{if(await ask('진행 중 보상을 변경합니다. 변경 전 규칙이 기록됩니다. 변경할까요?'))setEditingRule(true);}}>보상 규칙 변경</button>}</>}{r.changes.length>0&&<details><summary>보상 변경 기록 {r.changes.length}건</summary>{r.changes.map((c,i)=><p className="panel-note" key={i}>{date(c.at)} · 이전 규칙 {c.rule.type} / 참가 {c.rule.participation}</p>)}</details>}<p className="panel-note">게임을 시작하면 보상이 확정됩니다. 참가하지 않은 학생에게는 보상하지 않습니다.</p>{r.status==='scheduled'&&<button className="button primary" disabled={busy} onClick={async()=>void start(r)}><Play size={16}/> 보상 확정 · 회차 시작</button>}{editable&&<button className="button primary" onClick={async()=>{setEditingRule(false);setTab('result');}}>결과 입력으로 <ArrowRight size={16}/></button>}</div></div>}
 {tab==='result'&&<>{r.status==='scheduled'?<div className="empty"><Play/><h3>보상 규칙을 확인하고 회차를 시작해 주세요.</h3><button className="button primary" onClick={async()=>setTab('guide')}>보상 설정 확인</button></div>:<><div className="match-tabs">{r.matches.map((q,i)=><button key={q.id} className={q.id===m?.id?'selected':''} onClick={async()=>{setMatchIndex(i);setPreviewOn(false);}}>{q.name}</button>)}{editable&&<button onClick={async()=>void update((x,state)=>({...x,matches:[...x.matches,makeMatch(state,`경기 ${x.matches.length+1}`)]}))}><Plus size={14}/> 경기 추가</button>}</div><p className="panel-note">한 회차에서 여러 경기를 진행했다면 경기별 결과를 입력하세요. 보상은 경기별로 합산됩니다. {r.rule.type==='rank'?'같은 순위를 입력하면 공동 순위로 기록합니다.':''}</p>{m&&<><div className="match-title"><input aria-label="경기 이름" value={m.name} disabled={!editable} onChange={e=>{const value=e.target.value;void update(x=>({...x,matches:x.matches.map(q=>q.id===m.id?{...q,name:value}:q)}));}}/>{editable&&r.matches.length>1&&<button className="text-button danger" onClick={async()=>{if(await ask('이 경기 초안을 삭제할까요?')){void update(x=>({...x,matches:x.matches.filter(q=>q.id!==m.id)}));setMatchIndex(0);}}}>경기 삭제</button>}</div><div className="table-wrap"><table><thead><tr><th>학생</th><th>참가</th><th>{r.rule.type==='winner'?'공동 우승 가능':r.rule.type==='rank'?'순위 (공동 허용)':r.rule.type==='team'?'팀':'직접 배정'}</th><th>수동 조정</th><th>조정 사유 · 비공개</th><th>지급 예정</th></tr></thead><tbody>{m.entries.map(e=>{const student=s.students.find(x=>x.id===e.studentId)!;let amount='—';try{amount=String(calculate(r.rule,e).total);}catch{}return <tr key={e.studentId} className={!e.participated?'absent':''}><td><small>{student.number}번</small> {student.name}</td><td><input aria-label={`${student.name} 참가`} type="checkbox" checked={e.participated} disabled={!editable} onChange={ev=>patch(e.studentId,{participated:ev.target.checked})}/></td><td>{r.rule.type==='winner'?<input type="checkbox" aria-label={`${student.name} 우승`} disabled={!editable||!e.participated} checked={e.winner&&e.participated} onChange={ev=>patch(e.studentId,{winner:ev.target.checked})}/>:r.rule.type==='team'?<select aria-label={`${student.name} 팀`} value={e.team} disabled={!editable||!e.participated} onChange={ev=>patch(e.studentId,{team:ev.target.value})}>{!Object.keys(r.rule.teams).includes(e.team)&&<option value={e.team}>팀 선택 필요</option>}{Object.keys(r.rule.teams).map(t=><option key={t}>{t}</option>)}</select>:<input aria-label={`${student.name} ${r.rule.type==='rank'?'순위':'직접 배정'}`} type="number" min={r.rule.type==='rank'?1:0} disabled={!editable||!e.participated} value={r.rule.type==='rank'?(e.rank??''):e.direct} onChange={ev=>patch(e.studentId,r.rule.type==='rank'?{rank:ev.target.value===''?null:num(ev.target.value)}:{direct:num(ev.target.value)})}/>}</td><td><input aria-label={`${student.name} 수동 조정`} type="number" value={e.adjustment} disabled={!editable||!e.participated} onChange={ev=>patch(e.studentId,{adjustment:num(ev.target.value)})}/></td><td><input aria-label={`${student.name} 조정 사유`} value={e.reason} disabled={!editable} onChange={ev=>patch(e.studentId,{reason:ev.target.value})} maxLength={150} placeholder="선택 입력"/></td><td className="gold-text">{amount}</td></tr>;})}</tbody></table></div></>}{editable&&validation&&<p className="inline-error">{validation} 참가 학생의 결과 입력을 완료해 주세요.</p>}{(previewOn||r.status==='paid')&&!validation&&<div className="payment-preview"><h3>최종 지급안 <small>경기별 합산</small></h3><div className="table-wrap"><table><thead><tr><th>학생</th><th>참여 경기 수</th><th>참가 보상</th><th>결과 보상</th><th>수동 조정</th><th>최종 지급</th></tr></thead><tbody>{rows.map(x=><tr key={x.studentId}><td>{s.students.find(q=>q.id===x.studentId)?.name}</td><td>{x.count}회</td><td>{x.participation}</td><td>{x.result}</td><td>{x.adjustment}</td><td className="gold-text">{x.total} 가넷</td></tr>)}</tbody></table></div><strong className="total-line">총 {rows.reduce((n,x)=>n+x.total,0)} 가넷 · {rows.filter(x=>x.count).length}명 지급</strong></div>}<div className="modal-bottom">{r.status==='paid'?<><button className="button danger" disabled={busy} onClick={async()=>{if(await ask('이 회차의 전체 지급을 취소할까요? 원래 거래는 보존되고 반대 거래가 기록됩니다.'))void act(x=>cancelRound(x,r.id),'지급을 취소했습니다. 결과를 수정해 다시 지급할 수 있습니다.');}}><RotateCcw size={16}/> 회차 전체 지급 취소</button><button className="button primary" onClick={async()=>replay(r)}><Sparkles size={16}/> 연출 다시 보기</button></>:<><span className="muted">초안은 자동 저장됩니다.</span><div className="actions"><button className="button" disabled={!!validation||busy} onClick={async()=>setPreviewOn(true)}>지급안 확인</button><button className="button primary" disabled={!!validation||!previewOn||busy} onClick={async()=>void pay(r)}><Gem size={16}/> 가넷 지급 및 결과 공개</button></div></>}</div></> }</>}
 {tab==='tickets'&&<><p className="panel-note">미사용 이용권만 환불할 수 있습니다. 사용 완료·환불 처리는 중복할 수 없습니다.</p>{s.tickets.filter(t=>t.roundId===r.id).map(t=><div className="ticket-row" key={t.id}><div><strong>{s.students.find(x=>x.id===t.studentId)?.name} · {t.name}</strong><small>{t.price}가넷 · {t.status==='unused'?'미사용':t.status==='used'?'사용 완료':'환불 완료'}</small></div>{t.status==='unused'&&<><button className="button small" onClick={async()=>{if(await ask('이 이용권을 사용 완료로 기록할까요?'))void act(x=>{if(x.tickets.find(q=>q.id===t.id)?.status!=='unused')throw Error('이미 처리된 이용권입니다.');return {...x,tickets:x.tickets.map(q=>q.id===t.id?{...q,status:'used'}:q)};},'사용 완료 처리했습니다.');}}>사용 완료</button><button className="button small" onClick={async()=>{if(await ask('이 이용권을 환불할까요?'))void act(x=>refundTicket(x,t.id),'환불했습니다.');}}>환불</button></>}</div>)}{!s.tickets.some(t=>t.roundId===r.id)&&<div className="empty"><Gem/><h3>아직 발급한 이용권이 없습니다.</h3><p>고정 상품 정보 등록 후 구매할 수 있습니다.</p></div>}</>}
 </ModalBox>;
}
function StudentsModal({s,selectedId,close,act}:{s:State;selectedId?:string;close:()=>void;act:Act}){const [id,setId]=useState(selectedId??s.students[0]?.id??'');const p=s.students.find(x=>x.id===id);const [newNames,setNewNames]=useState('');const [starting,setStarting]=useState('0');const [kind,setKind]=useState<'bonus'|'purchase'|'adjust'>('bonus');const [amount,setAmount]=useState('1');const [reason,setReason]=useState('');const [editName,setEditName]=useState(p?.name??'');const [editNumber,setEditNumber]=useState(p?.number??'');useEffect(()=>{setEditName(p?.name??'');setEditNumber(p?.number??'');},[p?.id,p?.name,p?.number]);const t=p?totals(s,p.id):{balance:0,earned:0};return <ModalBox title="학생·가넷 장부" close={close} wide><div className="student-layout"><div className="student-sidebar"><h3>참가자 {s.students.filter(x=>x.active).length}명</h3><div className="student-picker">{s.students.map(x=><button key={x.id} className={x.id===id?'selected':''} onClick={async()=>setId(x.id)}>{x.number}. {x.name} {!x.active&&<small>비활성</small>}</button>)}</div><details><summary>학생 일괄 추가</summary><textarea value={newNames} onChange={e=>setNewNames(e.target.value)} placeholder={'17 김하늘\n18 이바다'}/><Field label="추가 학생 시작 가넷"><input type="number" min="0" value={starting} onChange={e=>setStarting(e.target.value)}/></Field><button className="button small" onClick={async()=>void act(x=>{integer(num(starting));const lines=newNames.split('\n').map(x=>x.trim()).filter(Boolean);if(!lines.length)throw Error('추가할 학생을 입력해 주세요.');const max=Math.max(0,...x.students.map(y=>Number(y.number)||0));const students=lines.map((line,i)=>{const m=line.match(/^(\d+)[\s,.]+(.+)$/);return {id:uid(),number:m?m[1]:String(max+i+1),name:m?m[2]:line,active:true};});checkStudents([...x.students,...students]);const next={...x,students:[...x.students,...students]};return {...next,ledger:[...x.ledger,...students.map(y=>transaction(next,y.id,'start',num(starting),0,'추가 학생 시작 지급'))]};},'학생을 추가했습니다.').then(ok=>{if(ok)setNewNames('');})}>학생 추가</button></details></div>{p?<div className="student-detail"><div className="student-top"><div><span className="eyebrow">PLAYER RECORD</span><h2>{p.name} <small>{p.number}번</small></h2></div><div className="student-totals"><span>누적 획득<strong>{fmt(t.earned)}</strong></span><span>현재 보유<strong>{fmt(t.balance)}</strong></span></div></div><div className="form-grid"><Field label="학생 이름"><input value={editName} onChange={e=>setEditName(e.target.value)} maxLength={80}/></Field><Field label="고유 번호"><input value={editNumber} onChange={e=>setEditNumber(e.target.value)} maxLength={20}/></Field></div><div className="actions"><button className="button small" onClick={async()=>void act(x=>{const students=x.students.map(y=>y.id===id?{...y,name:editName.trim(),number:editNumber.trim()}:y);checkStudents(students);return {...x,students};},'학생 정보를 저장했습니다.')}>이름·번호 저장</button><button className="text-button" onClick={async()=>{if(await ask(p.active?'기록이 있는 학생은 비활성 처리해 장부를 보존합니다. 처리할까요?':'이 학생을 다시 활성화할까요?'))void act(x=>{const has=x.ledger.some(t=>t.studentId===id)||x.rounds.some(r=>r.matches.some(m=>m.entries.some(e=>e.studentId===id)));return {...x,students:has?x.students.map(y=>y.id===id?{...y,active:!y.active}:y):x.students.filter(y=>y.id!==id)};});}}>{p.active?'삭제·비활성 처리':'다시 활성화'}</button></div><section className="adjust-box"><h3>가넷 기록 추가</h3><div className="form-grid"><Field label="거래 유형"><select value={kind} onChange={e=>setKind(e.target.value as typeof kind)}><option value="bonus">획득 보너스 · 순위 반영</option><option value="adjust">잔액만 조정 · 시작 가넷 예외 포함</option>{s.allowPurchase&&<option value="purchase">추가 구입 · 순위 제외</option>}</select></Field><Field label={kind==='adjust'?'증감량 (감소 시 음수)':'가넷 수량'}><input type="number" min={kind==='adjust'?-1000000:0} value={amount} onChange={e=>setAmount(e.target.value)}/></Field></div><Field label="사유 · 교사용 기록"><input value={reason} onChange={e=>setReason(e.target.value)} maxLength={150} placeholder="예: 시작 가넷 예외 조정"/></Field><div className="modal-bottom"><small>보유 {t.balance} → {t.balance+num(amount)} · 누적 {t.earned} → {t.earned+(kind==='bonus'?num(amount):0)}</small><button className="button primary small" onClick={async()=>{if(await ask('미리보기의 금액으로 장부에 기록할까요?'))void act(x=>{const n=num(amount);integer(n,kind==='adjust'?-1000000:0);if(n===0)throw Error('0 이외의 수량을 입력해 주세요.');if(kind==='purchase'&&!x.allowPurchase)throw Error('추가 구입이 비활성화되어 있습니다.');if(!reason.trim())throw Error('장부에 남길 사유를 입력해 주세요.');if(totals(x,id).balance+n<0)throw Error('보유 가넷을 음수로 만들 수 없습니다.');return {...x,ledger:[...x.ledger,transaction(x,id,kind,n,kind==='bonus'?n:0,reason.trim())]};},'가넷 기록을 저장했습니다.');}}>확인 후 기록</button></div></section><h3>전체 거래 기록 <small>장부는 삭제하지 않습니다.</small></h3><div className="table-wrap ledger"><table><thead><tr><th>시각</th><th>유형</th><th>보유 증감</th><th>누적 증감</th><th>사유</th></tr></thead><tbody>{s.ledger.filter(x=>x.studentId===id).toReversed().map(t=><tr key={t.id}><td>{date(t.at)}</td><td>{KINDS[t.kind]}</td><td>{t.balance>0?'+':''}{t.balance}</td><td>{t.earned>0?'+':''}{t.earned}</td><td>{t.reason}</td></tr>)}</tbody></table></div></div>:<div className="empty">학생을 선택하거나 추가해 주세요.</div>}</div></ModalBox>}
function BackupModal({s,close,restore,backed}:{s:State|null;close:()=>void;restore:(s:State)=>Promise<void>;backed:()=>void}){const [text,setText]=useState('');const [candidate,setCandidate]=useState<State|null>(null);const [err,setErr]=useState('');const [recoverBusy,setRecoverBusy]=useState(false);const validate=(t:string)=>{try{if(t.length>15000000)throw Error('백업 파일이 너무 큽니다.');const d=validateBackup(JSON.parse(t));setCandidate(d);setErr('');}catch(e){setCandidate(null);setErr((e as Error).message);}};const backup=()=>{if(s){download(JSON.stringify(s,null,2),'genius-season-backup.json');backed();}};return <ModalBox title="시즌 백업·복구" close={close}><p className="panel-note">백업 파일에는 학생 정보가 포함됩니다. 안전하게 보관해 주세요. 최근 정상 저장본도 같은 브라우저에 있으므로 별도 백업을 대체하지 못합니다.</p>{s&&<><div className="backup-status"><ShieldCheck/><div><strong>{s.name}</strong><small>마지막 백업: {s.lastBackup?date(s.lastBackup):'아직 없음'}</small></div></div><div className="actions"><button className="button primary" onClick={backup}><Download size={16}/> 전체 시즌 JSON 다운로드</button><button className="button" onClick={async()=>{try{await navigator.clipboard.writeText(JSON.stringify(s));backed();}catch{setText(JSON.stringify(s));setErr('클립보드에 접근할 수 없습니다. 아래 텍스트를 직접 복사해 주세요.');}}}><Copy size={16}/> 백업 텍스트 복사</button></div></>}<hr/><h3>기존 백업 불러오기</h3><label className="file-upload"><Upload size={18}/> JSON 파일 선택<input type="file" accept=".json,application/json" onChange={async e=>{const f=e.target.files?.[0];if(f){if(f.size>15000000){setErr('파일이 너무 큽니다.');return;}const t=await f.text();setText(t);validate(t);}}}/></label><Field label="백업 텍스트 붙여넣기"><textarea value={text} onChange={e=>{setText(e.target.value);setCandidate(null);}} placeholder="JSON 백업 텍스트"/></Field><div className="actions"><button className="button small" onClick={async()=>validate(text)}>복구 미리보기</button><button className="text-button" onClick={async()=>{const raw=localStorage.getItem(KEY+'-previous');if(raw){setText(raw);validate(raw);}else setErr('최근 정상 저장본이 없습니다.');}}>최근 정상 저장본 확인</button><button className="text-button" onClick={async()=>{const raw=localStorage.getItem(KEY);if(raw)download(raw,'genius-original-recovery.json');}}>현재 원본 보관</button></div>{err&&<p className="inline-error" role="alert">{err}</p>}{candidate&&<div className="restore-preview"><h3>{candidate.name}</h3><p>학생 {candidate.students.length}명 · 회차 {candidate.rounds.length}개 · 거래 {candidate.ledger.length}건</p><p>저장 시각 {date(candidate.updatedAt)}</p><button className="button primary" disabled={recoverBusy} onClick={async()=>{if(await ask('현재 데이터가 백업으로 교체됩니다. 기존 데이터 백업이 필요하면 취소 후 다운로드해 주세요. 복구할까요?')){setRecoverBusy(true);try{await restore(candidate);}finally{setRecoverBusy(false);}}}}>현재 데이터 교체 · 복구</button></div>}</ModalBox>}
function Reveal({s,r,close}:{s:State;r:Round;close:()=>void}){const rows=preview(r).filter(x=>x.count);const [count,setCount]=useState(s.settings.reduceMotion?1:0);useEffect(()=>{if(s.settings.reduceMotion||matchMedia('(prefers-reduced-motion: reduce)').matches){setCount(1);return;}const start=performance.now();let id:number;const frame=(now:number)=>{const value=Math.min(1,(now-start)/1200);setCount(value);if(value<1)id=requestAnimationFrame(frame);};id=requestAnimationFrame(frame);return()=>cancelAnimationFrame(id);},[]);return <div className="reveal-screen" role="dialog" aria-modal="true" aria-label="가넷 지급 결과"><button className="button skip" onClick={close}>연출 건너뛰기 <X size={17}/></button><span className="eyebrow">CHALLENGE COMPLETED</span><Diamond/><h1>{r.name}</h1><p>우리의 도전이 가넷으로 빛나는 순간</p><div className="reveal-grid" style={{maxWidth:Math.min(rows.length,6)*190}}>{rows.map(x=>{const student=s.students.find(y=>y.id===x.studentId)!;const t=totals(s,x.studentId);return <div className="reveal-card" key={x.studentId}><strong>{student.name}</strong><span><Gem size={20}/> +{Math.round(x.total*count)}</span><small>누적 {Math.round(t.earned-x.total+x.total*count)} · 보유 {Math.round(t.balance-x.total+x.total*count)}</small></div>;})}</div><p className="reveal-total">총 {rows.reduce((n,x)=>n+x.total,0)}가넷 지급 완료 · 기록이 저장되었습니다.</p><button className="button primary" onClick={close}>갱신된 순위 보기 <ArrowRight size={17}/></button></div>}
function ask(message:string):Promise<boolean>{return new Promise(resolve=>{const host=document.createElement('div');document.body.appendChild(host);const root=createRoot(host);const finish=(ok:boolean)=>{root.unmount();host.remove();resolve(ok);};root.render(<div className="confirm-layer"><ModalBox title="한 번 더 확인해 주세요" close={()=>finish(false)} eyebrow="PLEASE CONFIRM"><p className="confirm-message">{message}</p><div className="modal-bottom"><button className="button" onClick={()=>finish(false)}>취소</button><button className="button primary" onClick={()=>finish(true)}>확인하고 진행</button></div></ModalBox></div>);});}
function askText(message:string):Promise<string|null>{return new Promise(resolve=>{const host=document.createElement('div');document.body.appendChild(host);const root=createRoot(host);const finish=(v:string|null)=>{root.unmount();host.remove();resolve(v);};function TextDialog(){const [value,setValue]=useState('');return <div className="confirm-layer"><ModalBox title={message} close={()=>finish(null)}><input aria-label={message} value={value} onChange={e=>setValue(e.target.value)} maxLength={30}/><div className="modal-bottom"><button className="button" onClick={()=>finish(null)}>취소</button><button className="button primary" onClick={()=>finish(value)}>추가</button></div></ModalBox></div>;}root.render(<TextDialog/>);});}
createRoot(document.getElementById('root')!).render(<App/>);
